function classify(text) {
  const t = text.toLowerCase();
  if (t.includes('leak') || t.includes('read') || t.includes('seen')) return 'confidentiality';
  if (t.includes('tamper') || t.includes('changed') || t.includes('modify')) return 'integrity';
  if (t.includes('down') || t.includes('offline') || t.includes('slow')) return 'availability';
  return 'unknown';
}
const cases = ['Medical records leaked online', 'Transfer amount tampered in transit', 'Site knocked offline by traffic flood'];
for (const c of cases) console.log(c + ' -> ' + classify(c));

